import type { CoreRow } from "./i18n-core-errors";

/**
 * Páginas de informação (legal.ts): Termos de Uso, Política de Privacidade, Como apagar a conta,
 * Devoluções e reembolsos e as perguntas da Ajuda (HELP_FAQ).
 * Nota: o texto legal em português é o que vale; as traduções servem para ajudar a ler.
 */
export const CORE_LEGAL_ROWS: CoreRow[] = [
  ["Pode contactar-nos através da sua conta (Conta → Ajuda) ou denunciando o conteúdo em causa.", "You can contact us through your account (Account → Help) or by reporting the content concerned.", "您可以通过您的账户（账户 → 帮助）或举报相关内容来联系我们。", "Vous pouvez nous contacter depuis votre compte (Compte → Aide) ou en signalant le contenu concerné."],

  // --- Termos de Uso ---
  ["Estas regras valem para o Site e a APP Huambo Online. Ao criar conta ou usar o serviço, aceita estes termos.", "These rules apply to the Huambo Online website and app. By creating an account or using the service, you accept these terms.", "本规则适用于 Huambo Online 网站和应用。创建账户或使用服务即表示您接受这些条款。", "Ces règles s'appliquent au site et à l'application Huambo Online. En créant un compte ou en utilisant le service, vous acceptez ces conditions."],
  ["1. O que é o Huambo Online", "1. What Huambo Online is", "1. Huambo Online 是什么", "1. Ce qu'est Huambo Online"],
  ["Um lugar para comprar, vender, trocar e arrendar, encontrar profissionais e empresas, e pedir serviços no Huambo e em Angola.", "A place to buy, sell, swap and rent, find professionals and businesses, and request services in Huambo and across Angola.", "一个在万博及安哥拉各地买卖、交换和租赁，寻找专业人士和企业以及申请服务的平台。", "Un endroit pour acheter, vendre, échanger et louer, trouver des professionnels et des entreprises, et demander des services au Huambo et dans tout l'Angola."],
  ["O Huambo Online liga as pessoas. Os negócios são feitos entre comprador e vendedor (ou cliente e profissional), que são responsáveis pelo que combinam.", "Huambo Online connects people. Deals are made between buyer and seller (or customer and professional), who are responsible for what they agree.", "Huambo Online 连接人与人。交易在买卖双方（或客户与专业人士）之间进行，双方对约定内容负责。", "Huambo Online met les gens en relation. Les affaires se concluent entre acheteur et vendeur (ou client et professionnel), qui sont responsables de ce qu'ils conviennent."],
  ["2. A sua conta", "2. Your account", "2. 您的账户", "2. Votre compte"],
  ["Deve ter pelo menos 18 anos, ou autorização de quem tem a sua responsabilidade.", "You must be at least 18 years old, or have permission from your legal guardian.", "您必须年满18岁，或获得监护人的许可。", "Vous devez avoir au moins 18 ans, ou l'autorisation de votre représentant légal."],
  ["Os dados da conta devem ser verdadeiros. Guarde bem a sua palavra-passe: tudo o que for feito na sua conta é da sua responsabilidade.", "Your account details must be true. Keep your password safe: you are responsible for everything done on your account.", "账户信息必须真实。请妥善保管密码：您需对账户中的一切行为负责。", "Les données de votre compte doivent être exactes. Gardez bien votre mot de passe : vous êtes responsable de tout ce qui est fait avec votre compte."],
  ["Pode apagar a conta quando quiser (veja «Como apagar a minha conta»).", "You can delete your account whenever you want (see «How to delete my account»).", "您可以随时删除账户（参见「如何删除我的账户」）。", "Vous pouvez supprimer votre compte quand vous voulez (voir «Comment supprimer mon compte»)."],
  ["3. Anúncios, produtos e serviços", "3. Listings, products and services", "3. 信息、商品和服务", "3. Annonces, produits et services"],
  ["Só pode anunciar o que é seu ou o que tem autorização para vender, arrendar, trocar ou prestar.", "You may only list what is yours or what you are authorised to sell, rent, swap or provide.", "您只能发布属于您的物品，或您有权出售、出租、交换或提供的物品和服务。", "Vous ne pouvez proposer que ce qui vous appartient ou ce que vous êtes autorisé à vendre, louer, échanger ou fournir."],
  ["O título, o preço, as fotografias e a descrição devem corresponder à verdade. Indique se o preço é fixo, negociável, aberto a propostas, leilão ou troca.", "The title, price, photos and description must be truthful. State whether the price is fixed, negotiable, open to offers, an auction or a swap.", "标题、价格、照片和描述必须真实。请注明价格是固定、可议、接受报价、拍卖还是交换。", "Le titre, le prix, les photos et la description doivent être véridiques. Indiquez si le prix est fixe, négociable, ouvert aux offres, aux enchères ou en échange."],
  ["Garantia de conformidade: ao publicar, declara que o anúncio descreve o artigo com verdade e por completo, incluindo defeitos e o que falta. Se houver omissão ou erro, quem comprou ou arrendou tem direito a troca, devolução com reembolso ou reembolso (todo ou parte). Pode reclamar até 7 dias depois do negócio, em «Devoluções e reembolsos»; o dono responde em 3 dias e, se recusar ou não responder, a administração decide. Quem não cumprir a decisão pode ter a conta suspensa.", "Conformity guarantee: by publishing, you declare that the listing describes the item truthfully and completely, including defects and anything missing. If something is left out or wrong, the buyer or renter is entitled to an exchange, a return with refund, or a refund (full or partial). Claims can be made up to 7 days after the deal, in «Returns and refunds»; the owner replies within 3 days and, if they refuse or don't reply, the administration decides. Anyone who doesn't comply with the decision may have their account suspended.", "符合性保证：发布即表示您声明信息如实、完整地描述了物品，包括缺陷和缺少的部分。如有遗漏或错误，购买或租用者有权换货、退货退款或退款（全部或部分）。可在交易后7天内于「退货和退款」中投诉；物主须在3天内回复，若拒绝或未回复，由管理员裁决。不执行裁决者可能被暂停账户。", "Garantie de conformité : en publiant, vous déclarez que l'annonce décrit l'article avec vérité et de façon complète, y compris les défauts et ce qui manque. En cas d'omission ou d'erreur, l'acheteur ou le locataire a droit à un échange, un retour avec remboursement ou un remboursement (total ou partiel). La réclamation peut être faite jusqu'à 7 jours après l'affaire, dans «Retours et remboursements» ; le propriétaire répond sous 3 jours et, s'il refuse ou ne répond pas, l'administration décide. Quiconque ne respecte pas la décision peut voir son compte suspendu."],
  ["É proibido anunciar: armas, drogas, medicamentos sem autorização, animais protegidos, produtos roubados ou falsificados, documentos, conteúdos sexuais, e tudo o que a lei angolana proíba.", "It is forbidden to list: weapons, drugs, unauthorised medicines, protected animals, stolen or counterfeit goods, documents, sexual content, and anything prohibited by Angolan law.", "禁止发布：武器、毒品、未经许可的药品、受保护动物、被盗或假冒商品、证件、色情内容，以及安哥拉法律禁止的一切物品。", "Il est interdit de proposer : armes, drogues, médicaments non autorisés, animaux protégés, produits volés ou contrefaits, documents, contenus sexuels, et tout ce que la loi angolaise interdit."],
  ["A administração pode esconder ou retirar anúncios, produtos e perfis que não cumpram estas regras, e suspender contas.", "The administration may hide or remove listings, products and profiles that break these rules, and suspend accounts.", "管理员可以隐藏或删除违反这些规则的信息、商品和资料，并暂停账户。", "L'administration peut masquer ou retirer les annonces, produits et profils qui ne respectent pas ces règles, et suspendre des comptes."],
  ["4. Propostas, leilões, trocas e encomendas", "4. Offers, auctions, swaps and orders", "4. 报价、拍卖、交换和订单", "4. Offres, enchères, échanges et commandes"],
  ["Uma proposta aceite, um lance vencedor ou uma encomenda confirmada é um compromisso entre as duas pessoas. Cumpra o que combinou.", "An accepted offer, a winning bid or a confirmed order is a commitment between the two people. Keep to what you agreed.", "已接受的报价、获胜的出价或已确认的订单是双方之间的承诺。请履行约定。", "Une offre acceptée, une enchère gagnante ou une commande confirmée est un engagement entre les deux personnes. Respectez ce qui a été convenu."],
  ["Pode retirar uma proposta enquanto não tiver resposta. Um lance só pode ser retirado com motivo, se faltarem mais de 12 horas para o fim do leilão ou se foi feito há menos de 1 hora; quem retira lances muitas vezes pode ser impedido de licitar.", "You can withdraw an offer while it has no reply. A bid can only be withdrawn with a reason, if there are more than 12 hours until the auction ends or if it was made less than 1 hour ago; people who withdraw bids often may be blocked from bidding.", "在对方回复前，您可以撤回报价。出价只能在说明原因的情况下撤回，且须距拍卖结束超过12小时或出价不足1小时；频繁撤回出价者可能被禁止出价。", "Vous pouvez retirer une offre tant qu'elle n'a pas de réponse. Une enchère ne peut être retirée qu'avec un motif, s'il reste plus de 12 heures avant la fin de la vente ou si elle a été faite il y a moins d'1 heure ; les personnes qui retirent souvent leurs enchères peuvent être empêchées d'enchérir."],
  ["Nunca pague adiantado a quem não conhece. Prefira encontrar-se num local público, ver o artigo e pagar na entrega.", "Never pay in advance to someone you don't know. Prefer to meet in a public place, see the item and pay on delivery.", "切勿向陌生人预付款。最好在公共场所见面、看货并当面付款。", "Ne payez jamais d'avance quelqu'un que vous ne connaissez pas. Préférez vous rencontrer dans un lieu public, voir l'article et payer à la livraison."],
  ["Nas encomendas da Loja, o comprador pode pedir devolução, reembolso ou troca até 14 dias depois da entrega, e o vendedor deve responder. Veja «Devoluções e reembolsos».", "For Shop orders, the buyer can request a return, refund or exchange up to 14 days after delivery, and the seller must reply. See «Returns and refunds».", "对于商店订单，买家可在送达后14天内申请退货、退款或换货，卖家必须回复。参见「退货和退款」。", "Pour les commandes de la Boutique, l'acheteur peut demander un retour, un remboursement ou un échange jusqu'à 14 jours après la livraison, et le vendeur doit répondre. Voir «Retours et remboursements»."],
  ["5. Mensalidades e comissões", "5. Monthly fees and commissions", "5. 月费和佣金", "5. Mensualités et commissions"],
  ["Os perfis de profissionais e de empresas têm um mês grátis. Depois, pagam uma mensalidade à plataforma: 2 000 Kz por mês para profissionais e 5 000 Kz por mês para empresas (os valores em vigor aparecem em «O meu plano»).", "Professional and business profiles get one free month. After that, they pay the platform a monthly fee: 2 000 Kz per month for professionals and 5 000 Kz per month for businesses (current amounts are shown in «My plan»).", "专业人士和企业资料可享一个月免费。之后需向平台支付月费：专业人士每月2 000 Kz，企业每月5 000 Kz（现行金额见「我的套餐」）。", "Les profils professionnels et d'entreprise ont un mois gratuit. Ensuite, ils paient une mensualité à la plateforme : 2 000 Kz par mois pour les professionnels et 5 000 Kz par mois pour les entreprises (les montants en vigueur figurent dans «Mon forfait»)."],
  ["O pagamento é feito por transferência bancária ou Multicaixa Express, com a referência ou o comprovativo, e fica válido quando a administração o confirma.", "Payment is made by bank transfer or Multicaixa Express, with the reference or proof, and becomes valid once the administration confirms it.", "付款通过银行转账或 Multicaixa Express 进行，需提供参考号或付款凭证，经管理员确认后生效。", "Le paiement se fait par virement bancaire ou Multicaixa Express, avec la référence ou le justificatif, et devient valable une fois confirmé par l'administration."],
  ["As Lojas (produtos vendidos na Loja sem empresa) seguem o mesmo critério das empresas: um mês grátis e depois 5 000 Kz por mês. Os produtos de uma empresa ficam cobertos pela mensalidade dessa empresa.", "Shops (products sold in the Shop without a business) follow the same rule as businesses: one free month and then 5 000 Kz per month. A business's products are covered by that business's monthly fee.", "商店（不属于企业、在商店中销售的商品）与企业规则相同：一个月免费，之后每月5 000 Kz。企业的商品包含在该企业的月费中。", "Les Boutiques (produits vendus dans la Boutique sans entreprise) suivent la même règle que les entreprises : un mois gratuit puis 5 000 Kz par mois. Les produits d'une entreprise sont couverts par la mensualité de cette entreprise."],
  ["Sem mês grátis nem pagamento em dia, o perfil ou a Loja deixa de aparecer aos clientes, mas não é apagado. Volta a aparecer quando o pagamento é confirmado.", "Without a free month or an up-to-date payment, the profile or Shop stops being shown to customers, but it is not deleted. It reappears when payment is confirmed.", "若无免费月且未按时付款，资料或商店将不再向客户显示，但不会被删除。付款确认后将恢复显示。", "Sans mois gratuit ni paiement à jour, le profil ou la Boutique n'est plus montré aux clients, mais n'est pas supprimé. Il réapparaît dès que le paiement est confirmé."],
  ["Anúncios classificados não pagam mensalidade: quando um artigo é vendido (incluindo leilões), o vendedor paga à plataforma uma comissão de 5% do valor da venda, no prazo de 7 dias. O mesmo vale para o aluguer de bens móveis (viaturas, máquinas, etc.): 5% do valor indicado ao marcar «Arrendado», ou do valor total de um pedido de aluguer aceite. O arrendamento e o aluguer de imóveis são grátis: não pagam comissão. Com comissões em atraso não se podem publicar anúncios novos.", "Classified listings don't pay a monthly fee: when an item is sold (including auctions), the seller pays the platform a commission of 5% of the sale value within 7 days. The same applies to renting out movable goods (vehicles, machinery, etc.): 5% of the amount entered when marking “Rented”, or of the total amount of an accepted rental request. Renting out and leasing property is free: no commission. With overdue commissions, new listings can't be published.", "分类信息无需支付月费：物品售出（包括拍卖）时，卖家须在7天内向平台支付成交金额5%的佣金。动产（车辆、机械等）出租同样适用：按标记“已出租”时填写的金额或已接受租赁请求的总金额收取5%。房产出租免费，不收佣金。有逾期佣金时不能发布新信息。", "Les petites annonces ne paient pas de mensualité : quand un article est vendu (enchères comprises), le vendeur paie à la plateforme une commission de 5 % de la valeur de la vente, sous 7 jours. Il en va de même pour la location de biens mobiliers (véhicules, machines, etc.) : 5 % du montant indiqué en marquant «Loué», ou du montant total d'une demande de location acceptée. La location de biens immobiliers est gratuite : aucune commission. Avec des commissions en retard, il n'est pas possible de publier de nouvelles annonces."],
  ["Destaques (opcional): o vendedor pode pagar para o anúncio aparecer no topo das listas, com o selo «⭐ Destaque», durante o número de dias indicado (500 Kz por 7 dias, salvo outro valor anunciado). O destaque começa quando a administração confirma o pagamento e termina sozinho no fim do prazo. Não garante a venda.", "Featuring (optional): the seller can pay for the listing to appear at the top of lists, with the «⭐ Featured» badge, for the number of days stated (500 Kz for 7 days, unless another amount is announced). Featuring starts when the administration confirms payment and ends automatically at the end of the period. It does not guarantee a sale.", "推荐（可选）：卖家可付费让信息在列表顶部显示并带有「⭐ 推荐」标识，持续所示天数（7天500 Kz，另有公告除外）。推荐在管理员确认付款后开始，到期自动结束。推荐不保证售出。", "Mise à la une (facultative) : le vendeur peut payer pour que l'annonce apparaisse en tête des listes, avec le badge «⭐ À la une», pendant le nombre de jours indiqué (500 Kz pour 7 jours, sauf autre montant annoncé). La mise à la une commence quand l'administration confirme le paiement et se termine automatiquement à la fin de la période. Elle ne garantit pas la vente."],
  ["6. Pagamento protegido", "6. Protected payment", "6. 保障支付", "6. Paiement protégé"],
  ["Quando estiver disponível, pode escolher o «Pagamento protegido» nas compras da Loja. Paga ao Huambo Online, que guarda o dinheiro e só o entrega ao vendedor depois de o comprador confirmar que recebeu a encomenda.", "When available, you can choose «Protected payment» for Shop purchases. You pay Huambo Online, which holds the money and only releases it to the seller after the buyer confirms they received the order.", "开通后，您可在商店购物时选择「保障支付」。您向 Huambo Online 付款，由其托管款项，待买家确认收到订单后才交给卖家。", "Lorsqu'il est disponible, vous pouvez choisir le «Paiement protégé» pour les achats dans la Boutique. Vous payez Huambo Online, qui garde l'argent et ne le remet au vendeur qu'après que l'acheteur a confirmé avoir reçu la commande."],
  ["Se o comprador não confirmar nem reclamar dentro do prazo indicado depois da entrega (3 dias, salvo outro valor anunciado), o dinheiro é entregue ao vendedor. Um pedido de devolução ou reembolso aberto a tempo congela o dinheiro até ser resolvido.", "If the buyer neither confirms nor complains within the stated period after delivery (3 days, unless another period is announced), the money is released to the seller. A return or refund request opened in time freezes the money until it is resolved.", "如果买家在送达后的规定期限内（3天，另有公告除外）既未确认也未投诉，款项将交给卖家。及时提出的退货或退款申请会冻结款项直至解决。", "Si l'acheteur ne confirme pas et ne réclame pas dans le délai indiqué après la livraison (3 jours, sauf autre délai annoncé), l'argent est remis au vendeur. Une demande de retour ou de remboursement ouverte à temps gèle l'argent jusqu'à sa résolution."],
  ["Encomendas protegidas que não são pagas dentro do prazo indicado (48 horas, salvo outro valor anunciado) são canceladas. Os reembolsos de dinheiro ainda guardado são feitos pelo Huambo Online, para o IBAN ou o número Multicaixa Express indicado pelo comprador.", "Protected orders not paid within the stated period (48 hours, unless another period is announced) are cancelled. Refunds of money still held are made by Huambo Online, to the IBAN or Multicaixa Express number given by the buyer.", "未在规定期限内（48小时，另有公告除外）付款的保障订单将被取消。仍在托管中的款项由 Huambo Online 退还至买家提供的 IBAN 或 Multicaixa Express 号码。", "Les commandes protégées non payées dans le délai indiqué (48 heures, sauf autre délai annoncé) sont annulées. Les remboursements de l'argent encore retenu sont faits par Huambo Online, sur l'IBAN ou le numéro Multicaixa Express indiqué par l'acheteur."],
  ["O vendedor recebe as vendas libertadas no seu saldo e pede o levantamento para a sua conta. Os levantamentos são pagos por transferência nos dias anunciados em «O meu saldo». Se houver comissão sobre o pagamento protegido, é mostrada antes de vender e descontada no saldo.", "The seller receives released sales in their balance and requests a withdrawal to their account. Withdrawals are paid by transfer on the days announced in «My balance». If there is a commission on protected payment, it is shown before selling and deducted from the balance.", "卖家已释放的销售款进入其余额，可申请提现到自己的账户。提现在「我的余额」中公布的日期通过转账支付。如保障支付有佣金，会在出售前显示并从余额中扣除。", "Le vendeur reçoit les ventes versées dans son solde et demande un retrait vers son compte. Les retraits sont payés par virement les jours annoncés dans «Mon solde». S'il existe une commission sur le paiement protégé, elle est indiquée avant la vente et déduite du solde."],
  ["O Huambo Online atua apenas como intermediário tecnológico e de pagamento: não é o vendedor dos produtos nem responde pela sua qualidade, mas segue as regras de devolução descritas em «Devoluções e reembolsos».", "Huambo Online acts only as a technology and payment intermediary: it is not the seller of the products and is not responsible for their quality, but it follows the return rules described in «Returns and refunds».", "Huambo Online 仅作为技术和支付中介：并非商品的卖家，也不对商品质量负责，但遵循「退货和退款」中的退货规则。", "Huambo Online agit uniquement comme intermédiaire technologique et de paiement : il n'est pas le vendeur des produits et ne répond pas de leur qualité, mais il applique les règles de retour décrites dans «Retours et remboursements»."],
  ["7. Avaliações e denúncias", "7. Reviews and reports", "7. 评价和举报", "7. Évaluations et signalements"],
  ["Só quem fez negócio pode avaliar. As avaliações devem ser honestas e sem insultos.", "Only those who did business can leave a review. Reviews must be honest and free of insults.", "只有完成交易的人才能评价。评价必须诚实，不得辱骂。", "Seuls ceux qui ont fait affaire peuvent évaluer. Les évaluations doivent être honnêtes et sans insultes."],
  ["Se vir algo errado, use «Denunciar». A administração analisa as denúncias e pode retirar conteúdos.", "If you see something wrong, use «Report». The administration reviews reports and may remove content.", "如发现问题，请使用「举报」。管理员会审核举报并可能删除内容。", "Si vous voyez quelque chose d'anormal, utilisez «Signaler». L'administration examine les signalements et peut retirer des contenus."],
  ["8. Verificação de perfis", "8. Profile verification", "8. 资料认证", "8. Vérification des profils"],
  ["O selo «Verificado» quer dizer que a administração viu um documento. Não é uma garantia sobre a pessoa nem sobre o negócio: continue a ter cuidado.", "The «Verified» badge means the administration has seen a document. It is not a guarantee about the person or the deal: keep being careful.", "「已认证」标识表示管理员已查看过证件。这并不是对个人或交易的保证：请继续保持谨慎。", "Le badge «Vérifié» signifie que l'administration a vu un document. Ce n'est pas une garantie sur la personne ni sur l'affaire : restez prudent."],
  ["9. Responsabilidade", "9. Liability", "9. 责任", "9. Responsabilité"],
  ["O Huambo Online faz o possível para manter o serviço a funcionar e seguro, mas não garante que esteja sempre disponível nem responde pelos negócios feitos entre utilizadores.", "Huambo Online does its best to keep the service running and secure, but does not guarantee it will always be available and is not responsible for deals made between users.", "Huambo Online 尽力保持服务正常运行和安全，但不保证服务始终可用，也不对用户之间的交易负责。", "Huambo Online fait de son mieux pour que le service fonctionne et soit sûr, mais ne garantit pas qu'il soit toujours disponible et ne répond pas des affaires conclues entre utilisateurs."],
  ["Estes termos podem mudar. Quando mudarem, a data no topo é atualizada.", "These terms may change. When they do, the date at the top is updated.", "本条款可能会变更。变更时，顶部的日期会更新。", "Ces conditions peuvent changer. Lorsqu'elles changent, la date en haut de la page est mise à jour."],
  ["10. Contacto", "10. Contact", "10. 联系方式", "10. Contact"],

  // --- Política de Privacidade ---
  ["Explicamos que dados guardamos, para quê e quem os pode ver. Seguimos a Lei de Protecção de Dados Pessoais de Angola (Lei n.º 22/11).", "We explain what data we keep, what for and who can see it. We follow Angola's Personal Data Protection Law (Law no. 22/11).", "我们说明保存哪些数据、用途以及谁可以查看。我们遵守安哥拉《个人数据保护法》（第22/11号法律）。", "Nous expliquons quelles données nous conservons, pourquoi et qui peut les voir. Nous respectons la loi angolaise sur la protection des données personnelles (loi n° 22/11)."],
  ["1. Que dados guardamos", "1. What data we keep", "1. 我们保存哪些数据", "1. Quelles données nous conservons"],
  ["Conta: nome, e-mail, telefone (se o indicar), fotografia de perfil, município.", "Account: name, email, phone (if you provide it), profile photo, municipality.", "账户：姓名、电子邮箱、电话（如您提供）、头像、市镇。", "Compte : nom, e-mail, téléphone (si vous l'indiquez), photo de profil, municipalité."],
  ["O que publica: anúncios, produtos, fotografias, vídeos, preços, propostas, avaliações e respostas.", "What you post: listings, products, photos, videos, prices, offers, reviews and replies.", "您发布的内容：信息、商品、照片、视频、价格、报价、评价和回复。", "Ce que vous publiez : annonces, produits, photos, vidéos, prix, offres, évaluations et réponses."],
  ["Conversas: as mensagens que troca com outras pessoas.", "Conversations: the messages you exchange with other people.", "对话：您与他人互发的消息。", "Conversations : les messages que vous échangez avec d'autres personnes."],
  ["Negócios: encomendas, pedidos de serviço, alugueres, entregas e o histórico de cada um.", "Deals: orders, service requests, hires, deliveries and the history of each.", "交易：订单、服务申请、租用、配送及各自的历史记录。", "Affaires : commandes, demandes de service, locations, livraisons et l'historique de chacune."],
  ["Verificação (só se a pedir): a fotografia do documento (BI, alvará ou NIF).", "Verification (only if you request it): the photo of the document (ID card, licence or tax number).", "认证（仅在您申请时）：证件照片（身份证、营业执照或税号）。", "Vérification (seulement si vous la demandez) : la photo du document (carte d'identité, licence ou NIF)."],
  ["No telemóvel: guardamos no próprio aparelho os anúncios vistos e a última pesquisa, para poder ver sem internet.", "On your phone: we store the listings you viewed and your last search on the device itself, so you can see them without internet.", "在手机上：我们在设备本地保存您浏览过的信息和最近一次搜索，以便无网络时也能查看。", "Sur le téléphone : nous gardons sur l'appareil lui-même les annonces consultées et la dernière recherche, pour pouvoir les voir sans internet."],
  ["2. Para que usamos os dados", "2. What we use the data for", "2. 我们如何使用数据", "2. À quoi servent les données"],
  ["Para o serviço funcionar: mostrar anúncios, ligar compradores e vendedores, enviar notificações e mensagens, calcular avaliações e números do perfil.", "To run the service: showing listings, connecting buyers and sellers, sending notifications and messages, calculating ratings and profile figures.", "用于运行服务：展示信息、连接买家和卖家、发送通知和消息、计算评分和资料数据。", "Au fonctionnement du service : afficher les annonces, mettre en relation acheteurs et vendeurs, envoyer des notifications et des messages, calculer les évaluations et les chiffres du profil."],
  ["Para segurança: analisar denúncias, verificar perfis e impedir abusos.", "For security: reviewing reports, verifying profiles and preventing abuse.", "用于安全：审核举报、认证资料并防止滥用。", "À la sécurité : examiner les signalements, vérifier les profils et empêcher les abus."],
  ["Não vendemos os seus dados a ninguém e não mostramos publicidade com base neles.", "We don't sell your data to anyone and we don't show advertising based on it.", "我们不会向任何人出售您的数据，也不会基于这些数据投放广告。", "Nous ne vendons vos données à personne et n'affichons pas de publicité basée sur elles."],
  ["3. O que é público", "3. What is public", "3. 哪些内容是公开的", "3. Ce qui est public"],
  ["Os anúncios publicados, produtos, perfis de profissionais e empresas, o seu nome, a fotografia de perfil, as avaliações e os números do perfil (vendas, serviços prestados).", "Published listings, products, professional and business profiles, your name, profile photo, reviews and profile figures (sales, services provided).", "已发布的信息、商品、专业人士和企业资料、您的姓名、头像、评价和资料数据（销售、已提供服务）。", "Les annonces publiées, les produits, les profils de professionnels et d'entreprises, votre nom, la photo de profil, les évaluations et les chiffres du profil (ventes, services rendus)."],
  ["O seu e-mail, telefone, WhatsApp e localização (morada, indicações e ponto no mapa) não são mostrados a outros utilizadores. Só a equipa do Huambo Online (administração e moderadores) os vê. Os outros utilizadores falam consigo pelas Mensagens.", "Your email, phone, WhatsApp and location (address, directions and map point) are not shown to other users. Only the Huambo Online team (administrators and moderators) can see them. Other users contact you through Messages.", "您的电子邮箱、电话、WhatsApp 和位置（地址、路线说明和地图位置）不会向其他用户显示。只有 Huambo Online 团队（管理员和版主）可以看到。其他用户通过站内消息与您联系。", "Votre e-mail, téléphone, WhatsApp et localisation (adresse, indications et point sur la carte) ne sont pas montrés aux autres utilisateurs. Seule l'équipe de Huambo Online (administrateurs et modérateurs) peut les voir. Les autres utilisateurs vous contactent par les Messages."],
  ["Empresas, postos de combustível, hotéis, restaurantes e eventos mostram só a localização (morada e mapa), para poderem ser encontrados. O telefone e o WhatsApp deles também ficam só para a equipa. Pode apagar o seu número de WhatsApp quando quiser.", "Businesses, fuel stations, hotels, restaurants and events only show their location (address and map), so they can be found. Their phone and WhatsApp are also kept only for the team. You can delete your WhatsApp number at any time.", "企业、加油站、酒店、餐厅和活动只显示位置（地址和地图），以便被人找到。它们的电话和 WhatsApp 也仅供团队查看。您可以随时删除您的 WhatsApp 号码。", "Les entreprises, stations-service, hôtels, restaurants et événements ne montrent que leur localisation (adresse et carte), pour pouvoir être trouvés. Leur téléphone et leur WhatsApp sont aussi réservés à l'équipe. Vous pouvez supprimer votre numéro WhatsApp à tout moment."],
  ["4. O que é privado", "4. What is private", "4. 哪些内容是私密的", "4. Ce qui est privé"],
  ["As mensagens passam sempre pela equipa do Huambo Online (administração e moderadores), que as lê e as reencaminha à outra parte: os utilizadores não falam diretamente entre si. Encomendas, reservas, bilhetes, propostas, alugueres e pedidos de serviço também chegam primeiro à equipa, que os reencaminha a quem os vai tratar. O seu telefone e a sua morada só são partilhados quando forem precisos para a entrega ou o serviço.", "Messages always go through the Huambo Online team (administrators and moderators), who read them and forward them to the other party: users do not talk to each other directly. Orders, bookings, tickets, offers, rentals and service requests also go to the team first, who forward them to whoever will handle them. Your phone and address are only shared when needed for delivery or the service.", "所有消息都会先经过 Huambo Online 团队（管理员和版主），由团队阅读后转发给对方：用户之间不会直接交流。订单、预订、门票、报价、租赁和服务请求也会先到达团队，由团队转发给处理方。只有在配送或服务需要时，才会共享您的电话和地址。", "Les messages passent toujours par l'équipe de Huambo Online (administrateurs et modérateurs), qui les lit et les transmet à l'autre partie : les utilisateurs ne se parlent pas directement. Les commandes, réservations, billets, offres, locations et demandes de service arrivent aussi d'abord à l'équipe, qui les transmet à qui va s'en occuper. Votre téléphone et votre adresse ne sont partagés que lorsqu'ils sont nécessaires à la livraison ou au service."],
  ["Recomendações: para lhe sugerir anúncios, usamos os anúncios que vê, as pesquisas que faz e o que guarda (sem inteligência artificial). Só você vê este histórico; pode apagá-lo em «A sua conta» e é apagado sozinho ao fim de 90 dias.", "Recommendations: to suggest listings, we use the listings you view, your searches and what you save (no artificial intelligence). Only you can see this history; you can delete it in “Your account”, and it is deleted automatically after 90 days.", "推荐：为向您推荐信息，我们会使用您浏览的信息、搜索记录和收藏内容（不使用人工智能）。只有您能看到这些记录；您可以在“您的账户”中删除，记录也会在 90 天后自动删除。", "Recommandations : pour vous suggérer des annonces, nous utilisons les annonces que vous consultez, vos recherches et ce que vous enregistrez (sans intelligence artificielle). Vous seul voyez cet historique ; vous pouvez l'effacer dans «Votre compte» et il est effacé automatiquement au bout de 90 jours."],
  ["Avisos «✨ Novidades para si»: com o mesmo histórico, avisamos quando aparecem anúncios novos de que pode gostar (no máximo um aviso por dia, ou por semana). Para escolher os anúncios, as categorias, as palavras pesquisadas e os títulos dos anúncios que viu são enviados à OpenAI (nunca o seu nome, contactos ou mensagens). Pode mudar a frequência ou desligar em «Preferências de notificações».", "«✨ New for you» notices: with the same history, we let you know when new listings you may like appear (at most one notice a day, or a week). To choose the listings, the categories, searched words and titles of the listings you viewed are sent to OpenAI (never your name, contact details or messages). You can change the frequency or turn it off in “Notification preferences”.", "“✨ 为您推荐的新内容”通知：根据同样的记录，出现您可能喜欢的新信息时我们会通知您（每天或每周最多一条）。为挑选信息，您浏览过的类别、搜索词和信息标题会发送给 OpenAI（绝不包括您的姓名、联系方式或消息）。您可以在“通知偏好”中更改频率或关闭。", "Avis « ✨ Nouveautés pour vous » : avec le même historique, nous vous prévenons quand de nouvelles annonces qui pourraient vous plaire apparaissent (au maximum un avis par jour, ou par semaine). Pour choisir les annonces, les catégories, les mots recherchés et les titres des annonces consultées sont envoyés à OpenAI (jamais votre nom, vos coordonnées ni vos messages). Vous pouvez changer la fréquence ou désactiver dans « Préférences de notification »."],
  ["Os documentos de verificação ficam num espaço privado: só o próprio e a administração os podem abrir, através de uma ligação temporária.", "Verification documents are kept in a private space: only you and the administration can open them, through a temporary link.", "认证证件保存在私密空间：只有您本人和管理员可以通过临时链接打开。", "Les documents de vérification sont gardés dans un espace privé : seuls vous et l'administration pouvez les ouvrir, via un lien temporaire."],
  ["5. Onde ficam os dados e quem nos ajuda", "5. Where the data is kept and who helps us", "5. 数据存放在哪里以及谁为我们提供帮助", "5. Où sont les données et qui nous aide"],
  ["A base de dados e os ficheiros estão no Supabase, em servidores na União Europeia (Alemanha, Frankfurt).", "The database and files are on Supabase, on servers in the European Union (Germany, Frankfurt).", "数据库和文件存放在 Supabase，服务器位于欧盟（德国法兰克福）。", "La base de données et les fichiers sont chez Supabase, sur des serveurs dans l'Union européenne (Allemagne, Francfort)."],
  ["O Site está alojado na Vercel. A APP é feita com Expo.", "The website is hosted on Vercel. The app is built with Expo.", "网站托管在 Vercel。应用使用 Expo 开发。", "Le site est hébergé chez Vercel. L'application est faite avec Expo."],
  ["Pesquisa por fotografia (quando estiver ativa): a fotografia é enviada à OpenAI para dizer o que é o artigo, e não é guardada por nós.", "Photo search (when active): the photo is sent to OpenAI to identify the item, and is not stored by us.", "拍照搜索（开通后）：照片会发送给 OpenAI 以识别物品，我们不会保存照片。", "Recherche par photo (lorsqu'elle est active) : la photo est envoyée à OpenAI pour identifier l'article, et nous ne la conservons pas."],
  ["Melhorar com IA (só quando carrega no botão): o título, a descrição e os dados do anúncio são enviados à OpenAI para propor um texto melhor, e não são guardados por nós.", "Improve with AI (only when you tap the button): the listing's title, description and details are sent to OpenAI to suggest better text, and are not stored by us.", "AI 优化（仅在您点击按钮时）：信息的标题、描述和详情会发送给 OpenAI 以建议更好的文字，我们不会保存。", "Améliorer avec l'IA (seulement quand vous touchez le bouton) : le titre, la description et les données de l'annonce sont envoyés à OpenAI pour proposer un meilleur texte, et nous ne les conservons pas."],
  ["Fundo branco (só quando carrega no botão): a fotografia é tratada no nosso próprio servidor (Vercel), sem ser enviada a outras empresas, e não fica guardada; só fica a fotografia final, se a publicar.", "White background (only when you tap the button): the photo is processed on our own server (Vercel), without being sent to other companies, and is not stored; only the final photo is kept, if you publish it.", "白色背景（仅在您点击按钮时）：照片在我们自己的服务器（Vercel）上处理，不会发送给其他公司，也不会被保存；只有在您发布时才会保留最终照片。", "Fond blanc (uniquement quand vous touchez le bouton) : la photo est traitée sur notre propre serveur (Vercel), sans être envoyée à d'autres entreprises, et n'est pas conservée ; seule la photo finale est gardée, si vous la publiez."],
  ["Assistente de IA (só quando o usa): as fotografias para preencher um anúncio, o que escreve na pesquisa inteligente e as perguntas ao assistente de ajuda são enviadas à OpenAI para responder, e não são guardadas por nós. Os anúncios publicados podem ser traduzidos automaticamente para inglês, francês e chinês (as traduções ficam guardadas).", "AI assistant (only when you use it): photos used to fill in a listing, what you type in smart search and questions to the help assistant are sent to OpenAI to answer, and are not stored by us. Published listings can be translated automatically into English, French and Chinese (the translations are stored).", "AI 助手（仅在您使用时）：用于填写信息的照片、您在智能搜索中输入的内容以及向帮助助手提出的问题会发送给 OpenAI 以生成回答，我们不会保存。已发布的信息可能会被自动翻译成英文、法文和中文（译文会被保存）。", "Assistant IA (seulement quand vous l'utilisez) : les photos utilisées pour remplir une annonce, ce que vous tapez dans la recherche intelligente et les questions à l'assistant d'aide sont envoyés à OpenAI pour répondre, et nous ne les conservons pas. Les annonces publiées peuvent être traduites automatiquement en anglais, en français et en chinois (les traductions sont conservées)."],
  ["Segurança: os anúncios publicados são analisados automaticamente pela IA (OpenAI) para ajudar a equipa a encontrar burlas, artigos proibidos e contactos escondidos. A equipa também pode usar a IA para sugerir respostas nas Mensagens e resumir disputas. A IA só assinala e sugere: quem decide é sempre uma pessoa da equipa.", "Safety: published listings are checked automatically by AI (OpenAI) to help the team find scams, prohibited items and hidden contact details. The team can also use AI to suggest replies in Messages and to summarise disputes. AI only flags and suggests: a person on the team always makes the decision.", "安全：已发布的信息会由 AI（OpenAI）自动检查，帮助团队发现诈骗、违禁物品和隐藏的联系方式。团队也可以使用 AI 在消息中建议回复并总结纠纷。AI 只负责标记和建议：最终决定始终由团队成员作出。", "Sécurité : les annonces publiées sont analysées automatiquement par l'IA (OpenAI) pour aider l'équipe à repérer les arnaques, les articles interdits et les contacts cachés. L'équipe peut aussi utiliser l'IA pour suggérer des réponses dans les Messages et résumer des litiges. L'IA ne fait que signaler et suggérer : c'est toujours une personne de l'équipe qui décide."],
  ["Comprovativos de pagamento: os talões que envia são lidos pela IA (OpenAI) para ajudar a equipa a conferir o valor, a data e a conta de destino. A confirmação do pagamento é sempre feita por uma pessoa da equipa.", "Payment proofs: the receipts you send are read by AI (OpenAI) to help the team check the amount, date and destination account. The payment is always confirmed by a person on the team.", "付款凭证：您上传的收据会由 AI（OpenAI）读取，帮助团队核对金额、日期和收款账户。付款始终由团队成员确认。", "Justificatifs de paiement : les reçus que vous envoyez sont lus par l'IA (OpenAI) pour aider l'équipe à vérifier le montant, la date et le compte de destination. Le paiement est toujours confirmé par une personne de l'équipe."],
  ["6. Quanto tempo guardamos", "6. How long we keep data", "6. 数据保存多久", "6. Combien de temps nous conservons"],
  ["Enquanto a conta existir. Os vídeos de anúncios fechados ou vendidos são apagados automaticamente depois de 7 dias, e os de produtos escondidos depois de 30 dias.", "For as long as the account exists. Videos of closed or sold listings are deleted automatically after 7 days, and those of hidden products after 30 days.", "在账户存在期间保存。已关闭或已售信息的视频会在7天后自动删除，已隐藏商品的视频会在30天后删除。", "Tant que le compte existe. Les vidéos des annonces fermées ou vendues sont supprimées automatiquement au bout de 7 jours, et celles des produits masqués au bout de 30 jours."],
  ["Quando apaga a conta, os seus dados são apagados. Algumas cópias de segurança do fornecedor podem durar mais algum tempo até serem substituídas.", "When you delete your account, your data is deleted. Some of the provider's backups may last a little longer until they are replaced.", "删除账户后，您的数据会被删除。服务商的部分备份可能会多保留一段时间，直至被替换。", "Quand vous supprimez votre compte, vos données sont supprimées. Certaines sauvegardes du prestataire peuvent durer un peu plus longtemps jusqu'à être remplacées."],
  ["7. Os seus direitos", "7. Your rights", "7. 您的权利", "7. Vos droits"],
  ["Pode ver e corrigir os seus dados em «A sua conta», e apagar anúncios, produtos e a própria conta quando quiser.", "You can view and correct your data in «Your account», and delete listings, products and the account itself whenever you want.", "您可以在「您的账户」中查看和更正数据，并随时删除信息、商品和账户本身。", "Vous pouvez voir et corriger vos données dans «Votre compte», et supprimer annonces, produits et le compte lui-même quand vous voulez."],
  ["Pode pedir informação sobre os seus dados ou opor-se a um tratamento. Se achar que os seus direitos não foram respeitados, pode queixar-se à Agência de Protecção de Dados (APD) de Angola.", "You can ask for information about your data or object to its processing. If you think your rights have not been respected, you can complain to Angola's Data Protection Agency (APD).", "您可以申请了解您的数据或反对某项数据处理。如认为您的权利未受尊重，可向安哥拉数据保护局（APD）投诉。", "Vous pouvez demander des informations sur vos données ou vous opposer à un traitement. Si vous estimez que vos droits n'ont pas été respectés, vous pouvez porter plainte auprès de l'Agence de protection des données (APD) d'Angola."],
  ["8. Contacto", "8. Contact", "8. 联系方式", "8. Contact"],

  // --- Como apagar a minha conta ---
  ["Como apagar a minha conta", "How to delete my account", "如何删除我的账户", "Comment supprimer mon compte"],
  ["Pode apagar a sua conta do Huambo Online a qualquer momento, no Site ou na APP.", "You can delete your Huambo Online account at any time, on the website or in the app.", "您可以随时在网站或应用中删除您的 Huambo Online 账户。", "Vous pouvez supprimer votre compte Huambo Online à tout moment, sur le site ou dans l'application."],
  ["Passos", "Steps", "步骤", "Étapes"],
  ["1. Entre na sua conta (Site ou APP).", "1. Sign in to your account (website or app).", "1. 登录您的账户（网站或应用）。", "1. Connectez-vous à votre compte (site ou application)."],
  ["2. Abra «A sua conta».", "2. Open «Your account».", "2. 打开「您的账户」。", "2. Ouvrez «Votre compte»."],
  ["3. No fim da página, em «Eliminar conta», escreva ELIMINAR e confirme.", "3. At the bottom of the page, under «Delete account», type ELIMINAR and confirm.", "3. 在页面底部的「删除账户」中输入 ELIMINAR 并确认。", "3. En bas de la page, dans «Supprimer le compte», tapez ELIMINAR et confirmez."],
  ["O que é apagado", "What is deleted", "哪些内容会被删除", "Ce qui est supprimé"],
  ["A conta, o perfil, os anúncios, produtos, guardados, pesquisas guardadas, notificações e os dados ligados à conta.", "The account, profile, listings, products, saved items, saved searches, notifications and the data linked to the account.", "账户、资料、信息、商品、收藏、已保存的搜索、通知以及与账户关联的数据。", "Le compte, le profil, les annonces, les produits, les favoris, les recherches enregistrées, les notifications et les données liées au compte."],
  ["As avaliações que deixou a outras pessoas e as mensagens já enviadas podem ser apagadas ou ficar sem o seu nome.", "Reviews you left for other people and messages already sent may be deleted or remain without your name.", "您给他人留下的评价和已发送的消息可能会被删除，或保留但不显示您的姓名。", "Les évaluations que vous avez laissées à d'autres personnes et les messages déjà envoyés peuvent être supprimés ou rester sans votre nom."],
  ["Não consegue entrar?", "Can't sign in?", "无法登录？", "Vous n'arrivez pas à vous connecter ?"],
  ["Use «Esqueci-me da palavra-passe» na página de entrada para recuperar o acesso e depois apague a conta.", "Use «I forgot my password» on the sign-in page to recover access and then delete the account.", "请在登录页面使用「忘记密码」恢复访问，然后删除账户。", "Utilisez «J'ai oublié mon mot de passe» sur la page de connexion pour retrouver l'accès, puis supprimez le compte."],

  // --- Devoluções e reembolsos ---
  ["Como pedir a devolução, o reembolso ou a troca de uma encomenda feita na Loja do Huambo Online, e o que acontece em cada passo.", "How to request a return, refund or exchange for an order placed in the Huambo Online Shop, and what happens at each step.", "如何为在 Huambo Online 商店下的订单申请退货、退款或换货，以及每一步会发生什么。", "Comment demander le retour, le remboursement ou l'échange d'une commande passée dans la Boutique Huambo Online, et ce qui se passe à chaque étape."],
  ["Anúncios: o artigo tem de corresponder ao anúncio", "Listings: the item must match the listing", "信息：物品必须与信息相符", "Annonces : l'article doit correspondre à l'annonce"],
  ["Quem publica um anúncio declara que a descrição, as fotografias e o preço correspondem ao artigo, incluindo defeitos.", "Whoever publishes a listing declares that the description, photos and price match the item, including defects.", "发布信息者声明描述、照片和价格与物品相符，包括缺陷。", "Quiconque publie une annonce déclare que la description, les photos et le prix correspondent à l'article, défauts compris."],
  ["Se comprou ou arrendou e o artigo tem um defeito escondido, é diferente da descrição, é outro artigo ou faltam peças, abra o anúncio e carregue em «O artigo não corresponde ao anúncio» (até 7 dias depois do negócio).", "If you bought or rented and the item has a hidden defect, differs from the description, is a different item or has missing parts, open the listing and tap «The item doesn't match the listing» (up to 7 days after the deal).", "如果您购买或租用的物品有隐藏缺陷、与描述不符、是另一件物品或缺少零件，请打开该信息并点击「物品与信息不符」（交易后7天内）。", "Si vous avez acheté ou loué et que l'article a un défaut caché, diffère de la description, est un autre article ou qu'il manque des pièces, ouvrez l'annonce et touchez «L'article ne correspond pas à l'annonce» (jusqu'à 7 jours après l'affaire)."],
  ["Escolha o que quer: troca, devolução e reembolso, ou reembolso. O dono tem 3 dias para responder; se recusar ou não responder, peça à administração para decidir. As reclamações aparecem nesta página.", "Choose what you want: exchange, return and refund, or refund. The owner has 3 days to reply; if they refuse or don't reply, ask the administration to decide. Claims appear on this page.", "请选择您的诉求：换货、退货并退款或退款。物主有3天时间回复；若拒绝或未回复，请管理员裁决。投诉会显示在此页面。", "Choisissez ce que vous voulez : échange, retour et remboursement, ou remboursement. Le propriétaire a 3 jours pour répondre ; s'il refuse ou ne répond pas, demandez à l'administration de décider. Les réclamations apparaissent sur cette page."],
  ["1. Quando posso pedir", "1. When I can request", "1. 何时可以申请", "1. Quand puis-je faire une demande"],
  ["Numa encomenda da Loja que já pagou ou que já recebeu, até 14 dias depois da entrega.", "For a Shop order you've already paid for or received, up to 14 days after delivery.", "对于已付款或已收到的商店订单，可在送达后14天内申请。", "Pour une commande de la Boutique déjà payée ou reçue, jusqu'à 14 jours après la livraison."],
  ["Motivos: não recebeu, chegou estragado ou partido, é diferente do anúncio, artigo errado (modelo, tamanho, cor) ou faltam artigos.", "Reasons: not received, arrived damaged or broken, not as described in the listing, wrong item (model, size, colour) or items missing.", "原因：未收到、到货时已损坏或破碎、与信息描述不符、物品错误（型号、尺码、颜色）或缺少物品。", "Motifs : non reçue, arrivée endommagée ou cassée, ne correspond pas à l'annonce, mauvais article (modèle, taille, couleur) ou articles manquants."],
  ["Se a encomenda ainda está «Pendente», não precisa de pedido: carregue em «Cancelar».", "If the order is still «Pending», you don't need a request: tap «Cancel».", "如果订单仍为「待处理」，无需申请：直接点击「取消」。", "Si la commande est encore «En attente», pas besoin de demande : touchez «Annuler»."],
  ["2. O que posso pedir", "2. What I can request", "2. 可以申请什么", "2. Ce que je peux demander"],
  ["Reembolso: o vendedor devolve-lhe o dinheiro (todo ou parte).", "Refund: the seller gives you your money back (all or part).", "退款：卖家向您退还款项（全部或部分）。", "Remboursement : le vendeur vous rend l'argent (en totalité ou en partie)."],
  ["Devolução e reembolso: devolve o artigo ao vendedor e ele devolve-lhe o dinheiro.", "Return and refund: you return the item to the seller and they give you your money back.", "退货并退款：您将物品退回卖家，卖家向您退款。", "Retour et remboursement : vous rendez l'article au vendeur et il vous rend l'argent."],
  ["Troca: o vendedor envia-lhe outro artigo igual, em bom estado.", "Exchange: the seller sends you another identical item in good condition.", "换货：卖家给您寄一件完好的相同物品。", "Échange : le vendeur vous envoie un autre article identique, en bon état."],
  ["3. Como pedir", "3. How to request", "3. 如何申请", "3. Comment faire la demande"],
  ["Abra «Encomendas», escolha a encomenda e carregue em «Pedir devolução ou reembolso».", "Open «Orders», choose the order and tap «Request return or refund».", "打开「订单」，选择该订单并点击「申请退货或退款」。", "Ouvrez «Commandes», choisissez la commande et touchez «Demander un retour ou un remboursement»."],
  ["Escolha o motivo, explique o que aconteceu e junte até 4 fotografias. As fotografias ficam privadas: só o vendedor e a administração as veem.", "Choose the reason, explain what happened and add up to 4 photos. The photos stay private: only the seller and the administration see them.", "选择原因，说明发生了什么，并最多添加4张照片。照片是私密的：只有卖家和管理员可以查看。", "Choisissez le motif, expliquez ce qui s'est passé et joignez jusqu'à 4 photos. Les photos restent privées : seuls le vendeur et l'administration les voient."],
  ["Acompanhe tudo em «Devoluções e reembolsos». Cada passo envia uma notificação à outra pessoa.", "Follow everything in «Returns and refunds». Each step sends a notification to the other person.", "在「退货和退款」中跟进全部进展。每一步都会通知对方。", "Suivez tout dans «Retours et remboursements». Chaque étape envoie une notification à l'autre personne."],
  ["4. O que o vendedor faz", "4. What the seller does", "4. 卖家要做什么", "4. Ce que fait le vendeur"],
  ["Aceita o pedido ou recusa-o explicando o motivo.", "Accepts the request or declines it, explaining why.", "接受申请，或说明理由后拒绝。", "Il accepte la demande ou la refuse en expliquant pourquoi."],
  ["Se aceitar uma devolução, combinem pelas mensagens onde entregar o artigo. Quando o receber, confirma e devolve o dinheiro.", "If they accept a return, agree through messages where to hand over the item. When they receive it, they confirm and refund the money.", "如果接受退货，双方通过消息约定交还物品的地点。卖家收到后确认并退款。", "S'il accepte un retour, convenez par messages de l'endroit où remettre l'article. À la réception, il confirme et rembourse l'argent."],
  ["Quando devolver o dinheiro, carrega em «Já devolvi o dinheiro» e o comprador confirma que recebeu.", "When they refund the money, they tap «I've refunded the money» and the buyer confirms receipt.", "退款后，卖家点击「我已退款」，买家确认收到。", "Quand il rembourse, il touche «J'ai remboursé l'argent» et l'acheteur confirme la réception."],
  ["5. Se não se entenderem", "5. If you can't agree", "5. 如果双方无法达成一致", "5. Si vous ne vous entendez pas"],
  ["Se o vendedor recusar, pode chamar a administração logo. Se alguém não responder em 3 dias, qualquer um dos dois pode chamar a administração.", "If the seller declines, you can call in the administration straight away. If someone doesn't reply within 3 days, either of you can call in the administration.", "如果卖家拒绝，您可以立即请管理员介入。如果有一方3天内未回复，任何一方都可以请管理员介入。", "Si le vendeur refuse, vous pouvez faire appel à l'administration tout de suite. Si quelqu'un ne répond pas sous 3 jours, l'un ou l'autre peut faire appel à l'administration."],
  ["A administração vê o pedido, as mensagens e as fotografias, e decide: reembolso (todo ou parte), devolução, troca ou recusa. A decisão fica registada.", "The administration looks at the request, messages and photos, and decides: refund (full or partial), return, exchange or rejection. The decision is recorded.", "管理员会查看申请、消息和照片，并作出裁决：退款（全部或部分）、退货、换货或驳回。裁决会被记录。", "L'administration examine la demande, les messages et les photos, et décide : remboursement (total ou partiel), retour, échange ou rejet. La décision est enregistrée."],
  ["Quem não cumprir uma decisão pode ter a conta suspensa.", "Anyone who doesn't comply with a decision may have their account suspended.", "不执行裁决者可能被暂停账户。", "Quiconque ne respecte pas une décision peut voir son compte suspendu."],
  ["6. Encomenda paga e cancelada", "6. Order paid and cancelled", "6. 已付款但被取消的订单", "6. Commande payée puis annulée"],
  ["Se a encomenda já estava paga e foi cancelada, o pedido de reembolso abre sozinho: o vendedor tem de devolver o dinheiro todo.", "If the order was already paid and was cancelled, the refund request opens automatically: the seller must refund all the money.", "如果订单已付款后被取消，系统会自动发起退款申请：卖家必须全额退款。", "Si la commande était déjà payée et a été annulée, la demande de remboursement s'ouvre automatiquement : le vendeur doit rembourser la totalité."],
  ["Com pagamento protegido, quem devolve o dinheiro ainda guardado é o Huambo Online: indique no pedido o seu IBAN ou o número Multicaixa Express.", "With protected payment, Huambo Online refunds any money still held: enter your IBAN or Multicaixa Express number in the request.", "使用保障支付时，仍在托管中的款项由 Huambo Online 退还：请在申请中填写您的 IBAN 或 Multicaixa Express 号码。", "Avec le paiement protégé, c'est Huambo Online qui rembourse l'argent encore retenu : indiquez votre IBAN ou votre numéro Multicaixa Express dans la demande."],
  ["7. Como chega o dinheiro", "7. How the money arrives", "7. 款项如何到账", "7. Comment arrive l'argent"],
  ["Nas compras pagas ao vendedor (na entrega, transferência ou Multicaixa Express), o Huambo Online não guarda o dinheiro: o reembolso é feito pelo vendedor, pelo mesmo meio do pagamento, salvo outro acordo entre os dois.", "For purchases paid to the seller (on delivery, by transfer or Multicaixa Express), Huambo Online doesn't hold the money: the refund is made by the seller, by the same payment method, unless the two of you agree otherwise.", "对于直接付给卖家的购买（货到付款、转账或 Multicaixa Express），Huambo Online 不托管款项：退款由卖家以原付款方式退还，双方另有约定除外。", "Pour les achats payés au vendeur (à la livraison, par virement ou Multicaixa Express), Huambo Online ne garde pas l'argent : le remboursement est fait par le vendeur, par le même moyen de paiement, sauf autre accord entre vous."],
  ["Nas compras com pagamento protegido, o dinheiro fica guardado pelo Huambo Online até confirmar a receção. Enquanto estiver guardado, o reembolso é feito pelo Huambo Online. Depois de entregue ao vendedor, é o vendedor que devolve.", "For purchases with protected payment, Huambo Online holds the money until receipt is confirmed. While it is held, the refund is made by Huambo Online. Once released to the seller, it is the seller who refunds.", "使用保障支付的购买，款项由 Huambo Online 托管直至确认收货。托管期间由 Huambo Online 退款。款项交给卖家后，由卖家退款。", "Pour les achats avec paiement protégé, Huambo Online garde l'argent jusqu'à la confirmation de réception. Tant qu'il est retenu, le remboursement est fait par Huambo Online. Une fois remis au vendeur, c'est le vendeur qui rembourse."],
  ["Guarde os comprovativos de pagamento e de reembolso: podem ser pedidos pela administração.", "Keep proofs of payment and refund: the administration may ask for them.", "请保留付款和退款凭证：管理员可能会要求提供。", "Conservez les justificatifs de paiement et de remboursement : l'administration peut les demander."],
  ["8. Negócios fora da Loja", "8. Deals outside the Shop", "8. 商店以外的交易", "8. Affaires hors de la Boutique"],
  ["Nos anúncios classificados (venda, troca, arrendamento) o negócio é feito diretamente entre as pessoas, mas vale a garantia de conformidade: se o artigo não corresponder ao anúncio, use «O artigo não corresponde ao anúncio» na página do anúncio (veja acima). Para outros problemas, use «Denunciar» e a administração analisa.", "In classified listings (sale, swap, rental) the deal is made directly between people, but the conformity guarantee applies: if the item doesn't match the listing, use «The item doesn't match the listing» on the listing page (see above). For other problems, use «Report» and the administration will review it.", "在分类信息中（出售、交换、出租），交易直接在双方之间进行，但适用符合性保证：如果物品与信息不符，请在信息页面使用「物品与信息不符」（见上文）。其他问题请使用「举报」，由管理员审核。", "Dans les petites annonces (vente, échange, location), l'affaire se fait directement entre les personnes, mais la garantie de conformité s'applique : si l'article ne correspond pas à l'annonce, utilisez «L'article ne correspond pas à l'annonce» sur la page de l'annonce (voir plus haut). Pour d'autres problèmes, utilisez «Signaler» et l'administration examinera."],
  ["9. Contacto", "9. Contact", "9. 联系方式", "9. Contact"],

  // --- Ajuda (HELP_FAQ) ---
  ["Como publico um anúncio?", "How do I post a listing?", "如何发布信息？", "Comment publier une annonce ?"],
  ["Carregue em «Vender» ou «Publicar anúncio», escolha o tipo e a finalidade, diga como quer vender (preço fixo, negociável, propostas, leilão ou troca), junte fotografias e publique.", "Tap «Sell» or «Post listing», choose the type and purpose, say how you want to sell (fixed price, negotiable, offers, auction or swap), add photos and publish.", "点击「出售」或「发布信息」，选择类型和用途，说明出售方式（固定价格、可议价、接受报价、拍卖或交换），添加照片后发布。", "Touchez «Vendre» ou «Publier une annonce», choisissez le type et l'objectif, dites comment vous voulez vendre (prix fixe, négociable, offres, enchère ou échange), ajoutez des photos et publiez."],
  ["O que é «Preço fixo», «Negociável» e «Aberto a propostas»?", "What are «Fixed price», «Negotiable» and «Open to offers»?", "什么是「固定价格」、「可议价」和「接受报价」？", "Que signifient «Prix fixe», «Négociable» et «Ouvert aux offres» ?"],
  ["Preço fixo: quem quiser compra pelo preço indicado («Quero comprar»). Negociável: o comprador pode fazer uma proposta mais baixa. Aberto a propostas: o preço é só uma referência e os compradores dizem quanto pagam.", "Fixed price: anyone who wants it buys at the stated price («I want to buy»). Negotiable: the buyer can make a lower offer. Open to offers: the price is only a guide and buyers say how much they'll pay.", "固定价格：想买的人按标价购买（「我要买」）。可议价：买家可以提出更低的报价。接受报价：价格仅供参考，由买家出价。", "Prix fixe : qui le veut l'achète au prix indiqué («Je veux acheter»). Négociable : l'acheteur peut faire une offre plus basse. Ouvert aux offres : le prix n'est qu'une référence et les acheteurs disent combien ils paient."],
  ["Como funcionam as trocas?", "How do swaps work?", "交换如何进行？", "Comment fonctionnent les échanges ?"],
  ["Escolha «Só troca» ou marque «Também aceito troca» e diga o que aceita. Quem estiver interessado propõe um artigo (e pode juntar dinheiro). Veja todas em «Trocas».", "Choose «Swap only» or tick «I also accept swaps» and say what you'll accept. Anyone interested offers an item (and can add money). See them all in «Swaps».", "选择「仅限交换」或勾选「也接受交换」，并说明您接受什么。有兴趣的人会提出一件物品（也可以补差价）。在「以物易物」中查看全部。", "Choisissez «Échange uniquement» ou cochez «J'accepte aussi les échanges» et dites ce que vous acceptez. Les personnes intéressées proposent un article (et peuvent ajouter de l'argent). Retrouvez-les tous dans «Échanges»."],
  ["Como faço uma proposta?", "How do I make an offer?", "如何报价？", "Comment faire une offre ?"],
  ["No anúncio, carregue em «Fazer proposta», indique o valor e/ou o que oferece em troca. O vendedor aceita ou recusa e recebe uma notificação; acompanhe em «As minhas propostas».", "On the listing, tap «Make offer», enter the amount and/or what you're offering in exchange. The seller accepts or declines and gets a notification; follow it in «My offers».", "在信息页面点击「报价」，填写金额和/或您用于交换的物品。卖家会收到通知并选择接受或拒绝；可在「我的报价」中跟进。", "Sur l'annonce, touchez «Faire une offre», indiquez le montant et/ou ce que vous proposez en échange. Le vendeur accepte ou refuse et reçoit une notification ; suivez-la dans «Mes offres»."],
  ["Como retiro uma proposta?", "How do I withdraw an offer?", "如何撤回报价？", "Comment retirer une offre ?"],
  ["Em «As minhas propostas», carregue em «Retirar proposta». Só é possível enquanto o vendedor ainda não respondeu; depois de aceite, combine com ele pelas mensagens.", "In «My offers», tap «Withdraw offer». This is only possible while the seller hasn't replied yet; once accepted, sort it out with them through messages.", "在「我的报价」中点击「撤回报价」。只能在卖家尚未回复时撤回；报价被接受后，请通过消息与卖家协商。", "Dans «Mes offres», touchez «Retirer l'offre». Ce n'est possible que tant que le vendeur n'a pas répondu ; une fois acceptée, arrangez-vous avec lui par messages."],
  ["Como funcionam os leilões?", "How do auctions work?", "拍卖如何进行？", "Comment fonctionnent les enchères ?"],
  ["Como no eBay: escreva o MÁXIMO que está disposto a pagar. O Huambo Online licita por si só o necessário para ficar à frente, até esse máximo, que ninguém vê. Se outra pessoa oferecer mais do que o seu máximo, recebe um aviso e pode subir. Em caso de empate ganha quem licitou primeiro. Quem ganha paga o preço final, que muitas vezes é menor do que o seu máximo. Alguns leilões têm «Comprar já»: pode comprar logo por esse preço, até alguém licitar. Acompanhe tudo em «As minhas licitações»; recebe um aviso quando faltar menos de 1 hora.", "Like on eBay: enter the MAXIMUM you're willing to pay. Huambo Online bids for you only as much as needed to stay ahead, up to that maximum, which nobody sees. If someone else offers more than your maximum, you get a notice and can raise it. In a tie, whoever bid first wins. The winner pays the final price, which is often lower than their maximum. Some auctions have «Buy now»: you can buy straight away at that price, until someone bids. Follow everything in «My bids»; you get a notice when less than 1 hour is left.", "与 eBay 类似：输入您愿意支付的最高价。Huambo Online 会代您按需出价以保持领先，直至该最高价，且他人看不到。如果有人出价超过您的最高价，您会收到通知并可以加价。出价相同时，先出价者获胜。获胜者支付最终成交价，通常低于其最高价。部分拍卖设有「一口价」：在有人出价前可以直接按该价格购买。在「我的出价」中跟进全部进展；剩余不到1小时时会通知您。", "Comme sur eBay : indiquez le MAXIMUM que vous êtes prêt à payer. Huambo Online enchérit pour vous juste ce qu'il faut pour rester en tête, jusqu'à ce maximum, que personne ne voit. Si quelqu'un propose plus que votre maximum, vous êtes prévenu et pouvez monter. En cas d'égalité, c'est le premier enchérisseur qui gagne. Le gagnant paie le prix final, souvent inférieur à son maximum. Certaines enchères ont «Acheter maintenant» : vous pouvez acheter tout de suite à ce prix, jusqu'à ce que quelqu'un enchérisse. Suivez tout dans «Mes enchères» ; vous êtes prévenu quand il reste moins d'1 heure."],
  ["Como cancelo um lance num leilão?", "How do I cancel a bid in an auction?", "如何取消拍卖中的出价？", "Comment annuler une enchère ?"],
  ["No anúncio do leilão, abra «Ver lances» e carregue em «Retirar o meu lance», escolhendo o motivo. Pode fazê-lo se faltarem mais de 12 horas para o fim, ou se o lance foi feito há menos de 1 hora. No máximo 3 vezes em 30 dias. O vendedor também pode cancelar os lances de uma pessoa, explicando porquê.", "On the auction listing, open «See bids» and tap «Withdraw my bid», choosing the reason. You can do this if there are more than 12 hours until the end, or if the bid was made less than 1 hour ago. At most 3 times in 30 days. The seller can also cancel a person's bids, explaining why.", "在拍卖信息中打开「查看出价」，点击「撤回我的出价」并选择原因。距结束超过12小时或出价不足1小时时可以撤回。30天内最多3次。卖家也可以在说明理由后取消某人的出价。", "Sur l'annonce de la vente aux enchères, ouvrez «Voir les enchères» et touchez «Retirer mon enchère», en choisissant le motif. Vous pouvez le faire s'il reste plus de 12 heures avant la fin, ou si l'enchère a été faite il y a moins d'1 heure. 3 fois au maximum en 30 jours. Le vendeur peut aussi annuler les enchères d'une personne, en expliquant pourquoi."],
  ["O que é o número do anúncio (ex.: A-1001)?", "What is the listing number (e.g. A-1001)?", "什么是信息编号（例如：A-1001）？", "Qu'est-ce que le numéro de l'annonce (ex. : A-1001) ?"],
  ["Cada anúncio (A-…), produto (P-…) e encomenda (E-…) tem um número curto, que aparece na página. Use-o para falar com o vendedor ou com a administração, ou escreva-o na pesquisa para abrir o artigo diretamente.", "Every listing (A-…), product (P-…) and order (E-…) has a short number shown on its page. Use it when talking to the seller or the administration, or type it into search to open the item directly.", "每条信息（A-…）、商品（P-…）和订单（E-…）都有一个显示在页面上的短编号。与卖家或管理员沟通时可使用该编号，也可在搜索中输入以直接打开。", "Chaque annonce (A-…), produit (P-…) et commande (E-…) a un numéro court, affiché sur sa page. Utilisez-le pour parler au vendeur ou à l'administration, ou tapez-le dans la recherche pour ouvrir directement l'article."],
  ["Como mostro os meus trabalhos (portfólio)?", "How do I show my work (portfolio)?", "如何展示我的作品（作品集）？", "Comment montrer mes réalisations (portfolio) ?"],
  ["Profissionais: em «A sua conta» → «Perfil profissional» → «Portfólio», carregue em «Juntar trabalho», dê um título e junte até 8 fotografias. Empresas: em «As minhas empresas» → «Logótipo e portfólio». Os trabalhos aparecem na sua página pública, em «Trabalhos realizados», e pode mudar a ordem.", "Professionals: in «Your account» → «Professional profile» → «Portfolio», tap «Add work», give it a title and add up to 8 photos. Businesses: in «My businesses» → «Logo and portfolio». The works appear on your public page under «Completed work», and you can change the order.", "专业人士：在「您的账户」→「专业人士资料」→「作品集」中点击「添加作品」，填写标题并最多添加8张照片。企业：在「我的企业」→「标志和作品集」中操作。作品会显示在您的公开页面「已完成作品」中，并可调整顺序。", "Professionnels : dans «Votre compte» → «Profil professionnel» → «Portfolio», touchez «Ajouter une réalisation», donnez un titre et ajoutez jusqu'à 8 photos. Entreprises : dans «Mes entreprises» → «Logo et portfolio». Les réalisations apparaissent sur votre page publique, dans «Réalisations», et vous pouvez changer l'ordre."],
  ["Quanto custa ter perfil de profissional ou de empresa?", "How much does a professional or business profile cost?", "专业人士或企业资料收费多少？", "Combien coûte un profil de professionnel ou d'entreprise ?"],
  ["O primeiro mês é grátis. Depois, os profissionais pagam 2 000 Kz por mês e as empresas 5 000 Kz por mês. Pague em «A sua conta» → «O meu plano», com a referência ou o comprovativo da transferência ou do Multicaixa Express. Recebe avisos 7 dias e 1 dia antes do fim. Sem pagamento, o perfil deixa de aparecer aos clientes até pagar.", "The first month is free. After that, professionals pay 2 000 Kz per month and businesses 5 000 Kz per month. Pay in «Your account» → «My plan», with the reference or proof of the transfer or Multicaixa Express payment. You get reminders 7 days and 1 day before the end. Without payment, the profile stops being shown to customers until you pay.", "第一个月免费。之后专业人士每月2 000 Kz，企业每月5 000 Kz。请在「您的账户」→「我的套餐」中付款，并提供转账或 Multicaixa Express 的参考号或凭证。到期前7天和1天会收到提醒。未付款时，资料将不再向客户显示，直至付款。", "Le premier mois est gratuit. Ensuite, les professionnels paient 2 000 Kz par mois et les entreprises 5 000 Kz par mois. Payez dans «Votre compte» → «Mon forfait», avec la référence ou le justificatif du virement ou du Multicaixa Express. Vous êtes prévenu 7 jours et 1 jour avant la fin. Sans paiement, le profil n'est plus montré aux clients jusqu'au paiement."],
  ["Quanto custa vender na Loja e nos anúncios?", "How much does it cost to sell in the Shop and in listings?", "在商店和信息中出售收费多少？", "Combien coûte la vente dans la Boutique et dans les annonces ?"],
  ["Loja: o primeiro mês é grátis, depois 5 000 Kz por mês (se os produtos forem de uma empresa, basta a mensalidade da empresa). Anúncios: publicar é grátis; quando vende ou aluga bens (viaturas, máquinas…), paga uma comissão de 5% do valor em 7 dias, em «A sua conta» → «Comissões». Ao marcar «Vendido» ou «Arrendado» indica o valor e vê logo a comissão; num pedido de aluguer, a comissão é sobre o valor total aceite. O arrendamento de imóveis (casas, apartamentos, terrenos…) é grátis e sem comissões.", "Shop: the first month is free, then 5 000 Kz per month (if the products belong to a business, the business's monthly fee is enough). Listings: posting is free; when you sell or hire out goods (vehicles, machinery…), you pay a 5% commission on the amount within 7 days, in «Your account» → «Commissions». When marking «Sold» or «Rented» you enter the amount and see the commission straight away; for a hire request, the commission is on the total accepted amount. Renting out property (houses, apartments, land…) is free with no commissions.", "商店：第一个月免费，之后每月5 000 Kz（如商品属于企业，只需支付企业月费）。信息：发布免费；出售或出租物品（车辆、机械等）时，须在7天内于「您的账户」→「佣金」中支付金额5%的佣金。标记「已售出」或「已出租」时填写金额即可立即看到佣金；租用申请的佣金按已接受的总金额计算。房产（房屋、公寓、土地等）出租免费，无任何佣金。", "Boutique : le premier mois est gratuit, puis 5 000 Kz par mois (si les produits appartiennent à une entreprise, la mensualité de l'entreprise suffit). Annonces : publier est gratuit ; quand vous vendez ou louez des biens (véhicules, machines…), vous payez une commission de 5 % du montant sous 7 jours, dans «Votre compte» → «Commissions». En marquant «Vendu» ou «Loué», vous indiquez le montant et voyez tout de suite la commission ; pour une demande de location, la commission porte sur le montant total accepté. La location de biens immobiliers (maisons, appartements, terrains…) est gratuite et sans commission."],
  ["Como ponho o meu anúncio em destaque?", "How do I feature my listing?", "如何推荐我的信息？", "Comment mettre mon annonce à la une ?"],
  ["Em «Os meus anúncios», no anúncio publicado, carregue em «⭐ Destacar». Pague o valor indicado (500 Kz por 7 dias) por transferência ou Multicaixa Express e escreva a referência ou junte o comprovativo. Quando a administração confirmar, o anúncio aparece no topo das listas com o selo «⭐ Destaque». Pode prolongar antes de terminar.", "In «My listings», on the published listing, tap «⭐ Feature». Pay the amount shown (500 Kz for 7 days) by transfer or Multicaixa Express and enter the reference or attach the proof. When the administration confirms, the listing appears at the top of lists with the «⭐ Featured» badge. You can extend it before it ends.", "在「我的信息」中，于已发布的信息上点击「⭐ 推荐」。通过转账或 Multicaixa Express 支付所示金额（7天500 Kz），并填写参考号或附上凭证。管理员确认后，信息会带「⭐ 推荐」标识显示在列表顶部。到期前可以续期。", "Dans «Mes annonces», sur l'annonce publiée, touchez «⭐ Mettre à la une». Payez le montant indiqué (500 Kz pour 7 jours) par virement ou Multicaixa Express et indiquez la référence ou joignez le justificatif. Quand l'administration confirme, l'annonce apparaît en tête des listes avec le badge «⭐ À la une». Vous pouvez prolonger avant la fin."],
  ["Como sigo um profissional, uma empresa ou uma loja?", "How do I follow a professional, a business or a shop?", "如何关注专业人士、企业或商店？", "Comment suivre un professionnel, une entreprise ou une boutique ?"],
  ["Na página do profissional, da empresa ou do vendedor, carregue em «➕ Seguir». Recebe um aviso quando publicar um anúncio, um produto ou um trabalho novo (no máximo um aviso por hora de cada um). Veja quem segue em «A sua conta» → «A seguir»; para deixar de seguir, carregue em «✔ A seguir».", "On the professional's, business's or seller's page, tap «➕ Follow». You get a notice when they post a new listing, product or work (at most one notice per hour from each). See who you follow in «Your account» → «Following»; to unfollow, tap «✔ Following».", "在专业人士、企业或卖家的页面点击「➕ 关注」。对方发布新信息、商品或作品时您会收到通知（每个对象每小时最多一条）。在「您的账户」→「已关注」中查看关注列表；如需取消关注，请点击「✔ 已关注」。", "Sur la page du professionnel, de l'entreprise ou du vendeur, touchez «➕ Suivre». Vous êtes prévenu quand il publie une nouvelle annonce, un nouveau produit ou une nouvelle réalisation (au maximum un avis par heure de chacun). Voyez qui vous suivez dans «Votre compte» → «Abonnements» ; pour ne plus suivre, touchez «✔ Abonné»."],
  ["Como vendo produtos do campo (milho, batata, gado…)?", "How do I sell farm products (maize, potatoes, livestock…)?", "如何出售农产品（玉米、土豆、牲畜…）？", "Comment vendre des produits agricoles (maïs, pommes de terre, bétail…) ?"],
  ["Em «Vender», escolha o tipo «Artigo» ou «Outro» e ligue «🌾 Produto do campo». Diga o tipo (cereais, tubérculos, gado…), a unidade de venda (kg, saco de 50 kg, tonelada, cabeça…), a quantidade e, se ainda não colheu, a data «disponível a partir de». O preço aparece por unidade (ex.: 12 000 Kz / saco 50 kg) e o anúncio entra na secção «🌾 Agricultura e campo».", "In «Sell», choose the type «Item» or «Other» and switch on «🌾 Farm product». Say the type (cereals, tubers, livestock…), the sales unit (kg, 50 kg bag, tonne, head…), the quantity and, if you haven't harvested yet, the «available from» date. The price is shown per unit (e.g. 12 000 Kz / 50 kg bag) and the listing goes into the «🌾 Farming» section.", "在「出售」中选择「物品」或「其他」类型，并打开「🌾 农产品」。填写类型（谷物、块茎类、牲畜…）、销售单位（公斤、50公斤袋、吨、头…）、数量，如尚未收获，请填写「供货起始日期」。价格按单位显示（例如：12 000 Kz / 50公斤袋），信息将进入「🌾 农业」栏目。", "Dans «Vendre», choisissez le type «Article» ou «Autre» et activez «🌾 Produit agricole». Indiquez le type (céréales, tubercules, bétail…), l'unité de vente (kg, sac de 50 kg, tonne, tête…), la quantité et, si vous n'avez pas encore récolté, la date «disponible à partir du». Le prix s'affiche par unité (ex. : 12 000 Kz / sac de 50 kg) et l'annonce va dans la section «🌾 Agriculture»."],
  ["Como peço um serviço a um profissional?", "How do I request a service from a professional?", "如何向专业人士申请服务？", "Comment demander un service à un professionnel ?"],
  ["Abra a página do profissional ou empresa e use «Pedir serviço». Quando o serviço terminar, confirme e avalie — a avaliação fica marcada «Serviço confirmado».", "Open the professional's or business's page and use «Request service». When the service is finished, confirm and leave a review — the review is marked «Service confirmed».", "打开专业人士或企业的页面并使用「申请服务」。服务完成后请确认并评价——评价会标记为「服务已确认」。", "Ouvrez la page du professionnel ou de l'entreprise et utilisez «Demander un service». Quand le service est terminé, confirmez et évaluez — l'évaluation est marquée «Service confirmé»."],
  ["Como avalio um vendedor ou comprador?", "How do I review a seller or buyer?", "如何评价卖家或买家？", "Comment évaluer un vendeur ou un acheteur ?"],
  ["Depois de uma encomenda concluída, ou quando o anúncio é marcado como vendido com a pessoa certa, aparece em «Avaliações» para avaliar.", "After a completed order, or when the listing is marked as sold to the right person, it appears in «Reviews» for you to rate.", "订单完成后，或信息被标记为已售给对应的人后，会出现在「评价」中供您评价。", "Après une commande terminée, ou quand l'annonce est marquée comme vendue à la bonne personne, elle apparaît dans «Évaluations» pour que vous puissiez évaluer."],
  ["Como fico com o selo «Verificado»?", "How do I get the «Verified» badge?", "如何获得「已认证」标识？", "Comment obtenir le badge «Vérifié» ?"],
  ["Em «A sua conta», abra «Verificar perfil» e envie a fotografia do BI (ou do alvará/NIF da empresa). O documento fica privado; a administração responde por notificação.", "In «Your account», open «Verify profile» and send a photo of your ID card (or the business's licence/tax number). The document stays private; the administration replies by notification.", "在「您的账户」中打开「认证资料」，发送身份证照片（或企业的营业执照/税号）。证件保持私密；管理员会通过通知回复。", "Dans «Votre compte», ouvrez «Vérifier le profil» et envoyez la photo de votre carte d'identité (ou de la licence/NIF de l'entreprise). Le document reste privé ; l'administration répond par notification."],
  ["O que é o «Pagamento protegido»?", "What is «Protected payment»?", "什么是「保障支付」？", "Qu'est-ce que le «Paiement protégé» ?"],
  ["Nas compras da Loja, pode pagar ao Huambo Online em vez de pagar ao vendedor. Guardamos o dinheiro e o vendedor só o recebe depois de confirmar que recebeu a encomenda. Se houver problema, peça reembolso em «Encomendas»: o dinheiro fica congelado até se resolver. Se não confirmar nem reclamar uns dias depois da entrega, o pagamento vai para o vendedor.", "For Shop purchases, you can pay Huambo Online instead of paying the seller. We hold the money and the seller only gets it after you confirm you received the order. If there's a problem, ask for a refund in «Orders»: the money stays frozen until it's resolved. If you neither confirm nor complain within a few days of delivery, the payment goes to the seller.", "在商店购物时，您可以向 Huambo Online 付款，而不是直接付给卖家。我们托管款项，您确认收到订单后卖家才能收款。如有问题，请在「订单」中申请退款：款项将被冻结直至解决。如送达后数日内既未确认也未投诉，款项将交给卖家。", "Pour les achats dans la Boutique, vous pouvez payer Huambo Online au lieu de payer le vendeur. Nous gardons l'argent et le vendeur ne le reçoit qu'après que vous avez confirmé avoir reçu la commande. En cas de problème, demandez un remboursement dans «Commandes» : l'argent reste gelé jusqu'à la résolution. Si vous ne confirmez pas et ne réclamez pas quelques jours après la livraison, le paiement va au vendeur."],
  ["Vendo na Loja: como recebo o dinheiro do pagamento protegido?", "I sell in the Shop: how do I get protected payment money?", "我在商店出售：如何收到保障支付的款项？", "Je vends dans la Boutique : comment recevoir l'argent du paiement protégé ?"],
  ["Espere pelo aviso «Pagamento recebido» antes de enviar. Depois de entregar, marque a encomenda como «Entregue». Quando o cliente confirmar (ou passar o prazo sem reclamação), o dinheiro passa para «A sua conta» → «O meu saldo». Indique o seu IBAN ou número Multicaixa Express e carregue em «Pedir levantamento».", "Wait for the «Payment received» notice before shipping. After delivering, mark the order as «Delivered». When the customer confirms (or the period passes with no complaint), the money moves to «Your account» → «My balance». Enter your IBAN or Multicaixa Express number and tap «Request withdrawal».", "收到「已收到付款」通知后再发货。送达后，将订单标记为「已送达」。客户确认后（或期限内无投诉），款项会转入「您的账户」→「我的余额」。填写您的 IBAN 或 Multicaixa Express 号码，然后点击「申请提现」。", "Attendez l'avis «Paiement reçu» avant d'envoyer. Après la livraison, marquez la commande comme «Livrée». Quand le client confirme (ou que le délai passe sans réclamation), l'argent passe dans «Votre compte» → «Mon solde». Indiquez votre IBAN ou votre numéro Multicaixa Express et touchez «Demander un retrait»."],
  ["Como partilho um anúncio no WhatsApp?", "How do I share a listing on WhatsApp?", "如何在 WhatsApp 上分享信息？", "Comment partager une annonce sur WhatsApp ?"],
  ["Abra o anúncio ou o produto e carregue em «📲 Partilhar no WhatsApp». A mensagem leva o título, o preço, o número do anúncio (ex.: A-1023) e a ligação, e no WhatsApp aparece a fotografia. Escolha o contacto ou o grupo.", "Open the listing or product and tap «📲 Share on WhatsApp». The message includes the title, price, listing number (e.g. A-1023) and link, and the photo appears in WhatsApp. Choose the contact or group.", "打开信息或商品并点击「📲 分享到 WhatsApp」。消息包含标题、价格、信息编号（例如：A-1023）和链接，WhatsApp 中会显示照片。选择联系人或群组即可。", "Ouvrez l'annonce ou le produit et touchez «📲 Partager sur WhatsApp». Le message contient le titre, le prix, le numéro de l'annonce (ex. : A-1023) et le lien, et la photo apparaît dans WhatsApp. Choisissez le contact ou le groupe."],
  ["Os compradores podem ver o meu WhatsApp?", "Can buyers see my WhatsApp?", "买家能看到我的 WhatsApp 吗？", "Les acheteurs peuvent-ils voir mon WhatsApp ?"],
  ["Para proteger a sua privacidade, o seu número não é mostrado aos compradores: falam consigo pelas Mensagens do Huambo Online. Se guardar o seu WhatsApp em «A sua conta» → «WhatsApp», só a equipa do Huambo Online o vê.", "To protect your privacy, your number is not shown to buyers: they contact you through Huambo Online Messages. If you save your WhatsApp in “Your account” → “WhatsApp”, only the Huambo Online team can see it.", "为保护您的隐私，您的号码不会向买家显示：他们通过 Huambo Online 站内消息与您联系。如果您在“您的账户”→“WhatsApp”中保存号码，只有 Huambo Online 团队能看到。", "Pour protéger votre vie privée, votre numéro n'est pas montré aux acheteurs : ils vous contactent par les Messages de Huambo Online. Si vous enregistrez votre WhatsApp dans «Votre compte» → «WhatsApp», seule l'équipe de Huambo Online peut le voir."],
  ["Como funciona o «Convide um amigo»?", "How does «Invite a friend» work?", "「邀请好友」如何运作？", "Comment fonctionne «Inviter un ami» ?"],
  ["Em «Conta» → «Convidar amigos» tem o seu código e a sua ligação. Quem criar conta com o seu convite (nos primeiros 14 dias) fica ligado a si. Quando essa pessoa pagar a primeira mensalidade (profissional, empresa ou loja), ganha 1 mês grátis na sua mensalidade. Se ainda não tiver mensalidade, o prémio fica guardado.", "In «Account» → «Invite friends» you have your code and your link. Anyone who creates an account with your invite (within the first 14 days) is linked to you. When that person pays their first monthly fee (professional, business or shop), you earn 1 free month on your monthly fee. If you don't have a monthly fee yet, the reward is kept for you.", "在「账户」→「邀请好友」中有您的邀请码和链接。使用您的邀请创建账户的人（在前14天内）会与您关联。当对方支付首月月费（专业人士、企业或商店）时，您的月费可获赠1个月免费。如果您尚未有月费，奖励会为您保留。", "Dans «Compte» → «Inviter des amis», vous avez votre code et votre lien. Toute personne qui crée un compte avec votre invitation (dans les 14 premiers jours) vous est rattachée. Quand cette personne paie sa première mensualité (professionnel, entreprise ou boutique), vous gagnez 1 mois gratuit sur votre mensualité. Si vous n'avez pas encore de mensualité, la récompense est gardée."],
  ["O que é um agente no terreno?", "What is a field agent?", "什么是现场代理？", "Qu'est-ce qu'un agent de terrain ?"],
  ["É uma pessoa da praça (por exemplo, do Kapango) que ajuda os vendedores a pôr anúncios no Huambo Online. O anúncio fica sempre na conta do vendedor; ao publicar, o vendedor escreve o código do agente (ex.: AG1001). Quando esse anúncio é vendido, o agente ganha uma percentagem do valor da venda, que a administração confirma e que entra no saldo do agente. Para ser agente, abra «Conta» → «Ser agente».", "It's a person from the market (for example, Kapango) who helps sellers post listings on Huambo Online. The listing always stays in the seller's account; when publishing, the seller enters the agent's code (e.g. AG1001). When that listing is sold, the agent earns a percentage of the sale value, which the administration confirms and which goes into the agent's balance. To become an agent, open «Account» → «Become an agent».", "是市场中的人员（例如 Kapango 市场），帮助卖家在 Huambo Online 发布信息。信息始终在卖家的账户中；发布时，卖家填写代理编号（例如：AG1001）。该信息售出后，代理可获得成交金额的一定比例，经管理员确认后计入代理余额。如需成为代理，请打开「账户」→「成为代理」。", "C'est une personne du marché (par exemple, le Kapango) qui aide les vendeurs à publier des annonces sur Huambo Online. L'annonce reste toujours dans le compte du vendeur ; en publiant, le vendeur indique le code de l'agent (ex. : AG1001). Quand cette annonce est vendue, l'agent gagne un pourcentage de la valeur de la vente, confirmé par l'administration et versé dans son solde. Pour devenir agent, ouvrez «Compte» → «Devenir agent»."],
  ["E se o artigo não corresponder ao anúncio?", "What if the item doesn't match the listing?", "如果物品与信息不符怎么办？", "Et si l'article ne correspond pas à l'annonce ?"],
  ["Todos os anúncios têm garantia de conformidade: quem publica declara que a descrição é verdadeira e completa, incluindo defeitos. Se o artigo que comprou ou arrendou tiver um defeito escondido ou for diferente, abra o anúncio e carregue em «O artigo não corresponde ao anúncio» (até 7 dias depois do negócio). Pode pedir troca, devolução e reembolso, ou reembolso. Se o dono recusar ou não responder em 3 dias, a administração decide. Nas compras da Loja, use «Devoluções e reembolsos» na encomenda.", "All listings have a conformity guarantee: whoever publishes declares that the description is true and complete, including defects. If the item you bought or rented has a hidden defect or is different, open the listing and tap «The item doesn't match the listing» (up to 7 days after the deal). You can ask for an exchange, return and refund, or refund. If the owner refuses or doesn't reply within 3 days, the administration decides. For Shop purchases, use «Returns and refunds» on the order.", "所有信息都有符合性保证：发布者声明描述真实、完整，包括缺陷。如果您购买或租用的物品有隐藏缺陷或与描述不符，请打开该信息并点击「物品与信息不符」（交易后7天内）。您可以申请换货、退货并退款或退款。如果物主拒绝或3天内未回复，由管理员裁决。商店购物请在订单中使用「退货和退款」。", "Toutes les annonces ont une garantie de conformité : quiconque publie déclare que la description est vraie et complète, défauts compris. Si l'article acheté ou loué a un défaut caché ou est différent, ouvrez l'annonce et touchez «L'article ne correspond pas à l'annonce» (jusqu'à 7 jours après l'affaire). Vous pouvez demander un échange, un retour et remboursement, ou un remboursement. Si le propriétaire refuse ou ne répond pas sous 3 jours, l'administration décide. Pour les achats de la Boutique, utilisez «Retours et remboursements» sur la commande."],
  ["Como evito burlas?", "How do I avoid scams?", "如何防范诈骗？", "Comment éviter les arnaques ?"],
  ["Encontre-se num lugar público e movimentado (veja «Pontos de encontro seguros» em «Segurança»), veja o artigo e pague na entrega, ou use o Pagamento protegido na Loja. Nunca pague adiantado nem dê códigos que recebe por SMS ou o PIN. Nas mensagens, o Huambo Online avisa quando alguém pede pagamento adiantado ou códigos. Se suspeitar, use «Bloquear» e «Denunciar».", "Meet in a busy public place (see «Safe meeting points» in «Safety»), see the item and pay on delivery, or use Protected payment in the Shop. Never pay in advance or give out codes you receive by SMS or your PIN. In messages, Huambo Online warns you when someone asks for advance payment or codes. If you're suspicious, use «Block» and «Report».", "在人多的公共场所见面（参见「安全」中的「安全见面地点」），看货后当面付款，或在商店使用保障支付。切勿预付款，也不要透露短信验证码或 PIN。在消息中，如有人要求预付款或验证码，Huambo Online 会提醒您。如有怀疑，请使用「屏蔽」和「举报」。", "Rencontrez-vous dans un lieu public fréquenté (voir «Points de rencontre sûrs» dans «Sécurité»), voyez l'article et payez à la livraison, ou utilisez le Paiement protégé dans la Boutique. Ne payez jamais d'avance et ne donnez jamais les codes reçus par SMS ni votre PIN. Dans les messages, Huambo Online vous prévient quand quelqu'un demande un paiement anticipé ou des codes. En cas de doute, utilisez «Bloquer» et «Signaler»."],
  ["Como peço uma devolução ou reembolso?", "How do I request a return or refund?", "如何申请退货或退款？", "Comment demander un retour ou un remboursement ?"],
  ["Em «Encomendas», escolha a encomenda e carregue em «Pedir devolução ou reembolso» (até 14 dias depois da entrega). Explique o problema e junte fotografias. Se o vendedor recusar ou não responder, pode chamar a administração. Veja «Devoluções e reembolsos».", "In «Orders», choose the order and tap «Request return or refund» (up to 14 days after delivery). Explain the problem and add photos. If the seller declines or doesn't reply, you can call in the administration. See «Returns and refunds».", "在「订单」中选择订单并点击「申请退货或退款」（送达后14天内）。说明问题并添加照片。如果卖家拒绝或未回复，您可以请管理员介入。参见「退货和退款」。", "Dans «Commandes», choisissez la commande et touchez «Demander un retour ou un remboursement» (jusqu'à 14 jours après la livraison). Expliquez le problème et joignez des photos. Si le vendeur refuse ou ne répond pas, vous pouvez faire appel à l'administration. Voir «Retours et remboursements»."],
  ["Como gasto menos dados (saldo)?", "How do I use less data?", "如何节省流量？", "Comment consommer moins de données ?"],
  ["Ligue «📉 Poupar dados» no topo do Site, na página inicial da APP ou em «A sua conta». As fotografias das listas deixam de carregar (aparece um ícone) e, nos anúncios, só carregam quando tocar em «Ver as fotografias». Os vídeos só carregam quando carregar em ▶. No Site, «Automático» liga sozinho quando o telemóvel está em poupança de dados.", "Switch on «📉 Data saver» at the top of the website, on the app's home page or in «Your account». Photos in lists stop loading (an icon appears) and, on listings, they only load when you tap «See the photos». Videos only load when you tap ▶. On the website, «Automatic» switches on by itself when your phone is in data-saving mode.", "在网站顶部、应用首页或「您的账户」中打开「📉 节省流量」。列表中的照片将不再加载（显示为图标），信息中的照片只有在点击「查看照片」时才加载。视频只有在点击 ▶ 时才加载。在网站上，「自动」会在手机处于省流模式时自动开启。", "Activez «📉 Économie de données» en haut du site, sur la page d'accueil de l'application ou dans «Votre compte». Les photos des listes ne se chargent plus (une icône apparaît) et, dans les annonces, elles ne se chargent que lorsque vous touchez «Voir les photos». Les vidéos ne se chargent que lorsque vous touchez ▶. Sur le site, «Automatique» s'active tout seul quand le téléphone est en mode économie de données."],
  ["Como pago por transferência ou Multicaixa Express?", "How do I pay by bank transfer or Multicaixa Express?", "如何通过银行转账或 Multicaixa Express 付款？", "Comment payer par virement ou Multicaixa Express ?"],
  ["Use os dados para pagamento que aparecem no ecrã (IBAN ou n.º do Multicaixa Express) e pague o valor exato. Depois envie, no mesmo ecrã, uma fotografia nítida ou captura de ecrã do talão inteiro, onde se veja o valor, a data, a conta de destino e o n.º da operação. A equipa confere com o extrato do banco, confirma e recebe uma notificação.", "Use the payment details shown on the screen (IBAN or Multicaixa Express number) and pay the exact amount. Then, on the same screen, send a clear photo or screenshot of the whole receipt showing the amount, date, destination account and operation number. The team checks it against the bank statement, confirms it and you get a notification.", "使用屏幕上显示的付款信息（IBAN 或 Multicaixa Express 号码）支付准确金额。然后在同一页面上传完整收据的清晰照片或截图，需显示金额、日期、收款账户和交易编号。团队会核对银行流水并确认，您会收到通知。", "Utilisez les coordonnées de paiement affichées à l'écran (IBAN ou numéro Multicaixa Express) et payez le montant exact. Ensuite, sur le même écran, envoyez une photo nette ou une capture d'écran du reçu complet, où l'on voit le montant, la date, le compte de destination et le numéro de l'opération. L'équipe vérifie avec le relevé bancaire, confirme et vous recevez une notification."],
  ["O meu pagamento falhou ou foi recusado. O que faço?", "My payment failed or was rejected. What should I do?", "我的付款失败或被拒绝了，怎么办？", "Mon paiement a échoué ou a été refusé. Que faire ?"],
  ["Se o dinheiro não saiu da sua conta, tente de novo. Se saiu e o pagamento foi recusado, veja o motivo na notificação: normalmente o talão não se lê, o valor está errado ou foi pago para outra conta. Envie de novo o talão certo, ou fale com a equipa pelo WhatsApp ou pelas Mensagens indicando o n.º da operação. Nunca envie o PIN nem códigos que recebe por SMS.", "If the money didn't leave your account, try again. If it did and the payment was rejected, see the reason in the notification: usually the receipt can't be read, the amount is wrong or it was paid to another account. Send the right receipt again, or talk to the team on WhatsApp or through Messages, giving the operation number. Never send your PIN or codes you receive by SMS.", "如果钱没有从您的账户扣除，请重试。如果已扣款但付款被拒绝，请查看通知中的原因：通常是收据无法读取、金额错误或付到了其他账户。请重新上传正确的收据，或通过 WhatsApp 或站内消息联系团队并提供交易编号。切勿发送 PIN 或短信验证码。", "Si l'argent n'est pas sorti de votre compte, réessayez. S'il est sorti et que le paiement a été refusé, voyez le motif dans la notification : en général, le reçu est illisible, le montant est faux ou il a été payé sur un autre compte. Renvoyez le bon reçu, ou parlez à l'équipe sur WhatsApp ou par les Messages en indiquant le numéro de l'opération. N'envoyez jamais votre PIN ni les codes reçus par SMS."],
  ["O que faz o assistente de IA?", "What does the AI assistant do?", "AI 助手能做什么？", "Que fait l'assistant IA ?"],
  ["Ajuda a publicar e a encontrar mais depressa: «📷 Preencher pela foto» propõe o título, a categoria e os dados do anúncio a partir de uma fotografia; «✨ Melhorar com IA» reescreve o texto; «✨ Pesquisa inteligente» percebe pedidos como «carro diesel até 5 milhões»; e o assistente da Ajuda responde a dúvidas. Reveja sempre o que a IA propõe. Há um limite de usos por dia.", "It helps you post and find things faster: «📷 Fill in from photo» suggests the title, category and details of a listing from a photo; «✨ Improve with AI» rewrites the text; «✨ Smart search» understands requests like «diesel car up to 5 million»; and the Help assistant answers questions. Always review what the AI suggests. There is a daily usage limit.", "它能帮您更快地发布和查找：「📷 用照片填写」根据照片建议信息的标题、类别和详情；「✨ 用 AI 优化」重写文字；「✨ 智能搜索」能理解「500万以内的柴油车」之类的请求；帮助助手会回答您的问题。请始终检查 AI 的建议。每天有使用次数限制。", "Il vous aide à publier et à trouver plus vite : «📷 Remplir avec la photo» propose le titre, la catégorie et les données d'une annonce à partir d'une photo ; «✨ Améliorer avec l'IA» réécrit le texte ; «✨ Recherche intelligente» comprend des demandes comme «voiture diesel jusqu'à 5 millions» ; et l'assistant de l'Aide répond aux questions. Vérifiez toujours ce que l'IA propose. Il y a une limite d'utilisations par jour."],
  ["Posso usar sem internet?", "Can I use it without internet?", "没有网络可以使用吗？", "Puis-je l'utiliser sans internet ?"],
  ["Pode ver a página inicial, a última pesquisa e os últimos anúncios que abriu. Para publicar, enviar mensagens ou propostas precisa de ligação.", "You can see the home page, your last search and the last listings you opened. To publish, send messages or offers you need a connection.", "您可以查看首页、最近一次搜索和最近打开的信息。发布、发送消息或报价需要联网。", "Vous pouvez voir la page d'accueil, votre dernière recherche et les dernières annonces ouvertes. Pour publier, envoyer des messages ou des offres, il faut une connexion."],
  ["Como apago a minha conta?", "How do I delete my account?", "如何删除我的账户？", "Comment supprimer mon compte ?"],
  ["Em «A sua conta», no fim da página, escreva ELIMINAR e confirme. Veja os pormenores em «Como apagar a minha conta».", "In «Your account», at the bottom of the page, type ELIMINAR and confirm. See the details in «How to delete my account».", "在「您的账户」页面底部输入 ELIMINAR 并确认。详情参见「如何删除我的账户」。", "Dans «Votre compte», en bas de la page, tapez ELIMINAR et confirmez. Voir les détails dans «Comment supprimer mon compte»."]
];
